import{_ as a,c as n,o as t,ag as r}from"./chunks/framework.Vyheyqg9.js";const f=JSON.parse('{"title":"Coordinate larger changes","description":"","frontmatter":{},"headers":[],"relativePath":"ai-assisted-engineering/advanced-coordination.md","filePath":"ai-assisted-engineering/advanced-coordination.md"}'),i={name:"ai-assisted-engineering/advanced-coordination.md"};function o(s,e,c,d,l,h){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="_7-coordinate-larger-changes" tabindex="-1">Coordinate larger changes <a class="header-anchor" href="#_7-coordinate-larger-changes" aria-label="Permalink to “Coordinate larger changes”">​</a></h1><p>Begin with one assistant and one clear task. Additional agents or worktrees help only when they remove a concrete bottleneck, such as an independent review or two changes with separate file ownership.</p><h2 id="choose-the-form-of-separation" tabindex="-1"><span class="hub-section-number">1 </span>Choose the form of separation <a class="header-anchor" href="#choose-the-form-of-separation" aria-label="Permalink to “1 Choose the form of separation”">​</a></h2><p>A branch separates history. A worktree provides another checkout directory. Neither is an OS security boundary: credentials, ports, services and caches may still be shared. The <a href="./local-workflow-and-git.html">existing Git lesson</a> contains the detailed experiment and preservation rules.</p><p>Two assistants editing the same function concurrently can overwrite assumptions even when the tools report success. Assign independent scopes and designate one integration owner. A reasonable split is implementation in one checkout and read-only review of the exact candidate in another; do not ask reviewers to silently repair files while reviewing.</p><h2 id="define-a-handoff-contract" tabindex="-1"><span class="hub-section-number">2 </span>Define a handoff contract <a class="header-anchor" href="#define-a-handoff-contract" aria-label="Permalink to “2 Define a handoff contract”">​</a></h2><p>Give a reviewer the task, exact candidate/diff, relevant context, verification results and required output. Ask for actionable findings with triggering inputs. The integrating owner must reconcile them, inspect the final diff and rerun affected checks. A review of an earlier revision does not automatically approve later changes.</p><p>For two implementation subtasks, specify owned files or interfaces, expected outputs and dependencies first. Parallel work is less useful when both subtasks require frequent changes to one shared contract. Start serially if that makes integration clearer.</p><h2 id="keep-aggregate-limits-and-evidence" tabindex="-1"><span class="hub-section-number">3 </span>Keep aggregate limits and evidence <a class="header-anchor" href="#keep-aggregate-limits-and-evidence" aria-label="Permalink to “3 Keep aggregate limits and evidence”">​</a></h2><p>Several agents may duplicate calls and context. The task still needs an overall scope/time/cost limit, one final acceptance map and a clear record of what actually ran. Agreement between agents is not independent evidence if they share the same mistaken premise.</p><p>Persist enough state to resume, then reinspect the repository. Never reset or delete user work just to obtain a clean checkout. Follow the no-push rule even if a generated plan proposes publication.</p><p><strong>Optional exercise:</strong> after finishing your own feature, ask a separate reviewer to assess the frozen candidate read-only. Record a real finding or an explicitly limited no-findings result. Explain whether the extra review improved the outcome enough to justify the effort.</p><p><strong>Done:</strong> you can choose single-owner work by default, explain when separation helps and reconcile the final candidate. Continue with your own project or <a href="./traceability-and-evaluation.html">the advanced traceability material</a>; multiple agents are not required for the beginner course.</p>',13)])])}const g=a(i,[["render",o]]);export{f as __pageData,g as default};
